import React from 'react'
import "./Item.css";
import { Link } from 'react-router-dom';
const Item = (props) => {
  {console.log("id is", props.id)}
  return (
    <div className='item'>
    {/* <Link to={`/product/{props.id}`}> <img  className={`product-image ${props.imageClass || ""}`} src={props.image} alt="" />  </Link>   */}
<Link to={`/product/${props.id}`}>View Product</Link>


      <p>{props.name}</p>
      <div className="item-prices">
        <div className="item-price-new">
             ${props.new_price}
        </div>
        <div className="item-price-old">
           ${props.old_price}
        </div>
      </div>
    </div>

  )
}

export default Item
